/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from "@wordpress/i18n";

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import {
	useBlockProps,
	InspectorControls,
	PanelColorSettings,

} from "@wordpress/block-editor";
import {
	Button,
	PanelBody,
	SelectControl,
	ToggleControl,
	TextControl,
} from "@wordpress/components";
import { Fragment, useEffect } from "@wordpress/element";

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import "./editor.scss";

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit({ attributes, setAttributes }) {
	const { enableTourCountDown, buttonLabel, whatsappIconColor, whatsappLinkTextColor } = attributes

	const whatsappIconColorSettings = [
		{
			value: whatsappIconColor,
			onChange: colorValue => setAttributes({ whatsappIconColor: colorValue }),
			label: __( "WhatsApp Icon Color", 'wp-travel-blocks' )
		}
	];

	const whatsappLinkTextcolorSettings = [
		{
			value: whatsappLinkTextColor,
			onChange: colorValue => setAttributes({ whatsappLinkTextColor: colorValue }),
			label: __( "WhatsApp Link Text Color", 'wp-travel-blocks' )
		}
	];

	return (
		<div {...useBlockProps()}>
			<InspectorControls>
				<PanelBody
					title={__("Whatsapp Enquiry Button Settings", "wens-haelo-pro")}
					initialOpen={true}
				>
					 {/* <ToggleControl
						label={__("Enable Tour Date CountDown")}
						checked={enableTourCountDown}
						onChange={() =>
						setAttributes({
							enableTourCountDown: !enableTourCountDown,
						})
						}
					/> */}
					<TextControl
						label={ __( 'Button Label', 'wp-travel-blocks' ) }
						value={ buttonLabel }
						onChange={ (value) => setAttributes( { buttonLabel: value } ) }
					/>
					
					<PanelColorSettings
						title={__('WhatsApp Icon Color', 'wp-travel-blocks')}
						colorSettings={whatsappIconColorSettings}
						initialOpen={false}
					/>

					<PanelColorSettings
						title={__('WhatsApp Link Text Color', 'wp-travel-blocks')}
						colorSettings={whatsappLinkTextcolorSettings}
						initialOpen={false}
					/>

				</PanelBody>
			</InspectorControls>
			<a id="wp-travel-send-message-whatsapp" className="wp-travel-message-whatsapp" data-effect="mfp-move-from-top" href="#">
				<span className="wp-travel-booking-enquiry-message">
					<span className="wp-travel-whatsapp-icon">
						<i className="fab fa-whatsapp"
							style={{
								color: whatsappIconColor,
							}}
						>							
						</i>
					</span>
					<span
						style={{
							color: whatsappLinkTextColor,
						}}
					>
						{buttonLabel}
					</span>
				</span>
			</a>
		</div>
	);
}

